#pragma once
#include "OneShotPreparation.h"
class OneShotPreparationPanel final:public juce::Component,private juce::ListBoxModel,private juce::Timer {
 std::vector<OneShotPreparation::Item> rows;juce::ListBox list{"One-shots",this};juce::Label title,detail,status;
 juce::Slider root,cents;juce::TextButton sampleButton{"PLAY SAMPLE"},pianoButton{"PIANO REFERENCE"},detect{"DETECT AGAIN"},retuneSelected{"RETUNE SELECTED → C"},retuneAll{"RETUNE ALL → C"},move{"MOVE SELECTED..."},restore{"RESTORE LAST BATCH"};bool loading=false,binding=false;juce::String resultText;int active=-1;
public:
 std::function<void(double)> piano;std::function<void(std::shared_ptr<const AudioData>)> audition;std::function<void()> stop;std::function<void(juce::Array<juce::File>)> moveFiles,changed;
 explicit OneShotPreparationPanel(juce::Array<juce::File> files){setSize(710,500);for(auto f:files)if(!f.isDirectory()){OneShotPreparation::Item item;item.file=f;item.status="Waiting for pitch detection";rows.push_back(item);}for(auto* c:std::vector<juce::Component*>{&list,&title,&detail,&status,&root,&cents,&sampleButton,&pianoButton,&detect,&retuneSelected,&retuneAll,&move,&restore})addAndMakeVisible(c);title.setText("ONE-SHOT PREPARATION • nearest C",juce::dontSendNotification);title.setBounds(12,8,686,25);list.setBounds(12,38,686,248);list.setRowHeight(25);list.setMultipleSelectionEnabled(true);detail.setBounds(12,292,300,23);detail.setText("Active row pitch (editable):",juce::dontSendNotification);root.setBounds(12,318,332,30);cents.setBounds(358,318,340,30);root.setRange(-1,127,1);root.setSliderStyle(juce::Slider::LinearHorizontal);root.setTextBoxStyle(juce::Slider::TextBoxRight,false,70,26);root.textFromValueFunction=[](double value){return SamplePitch::name((int)value);};root.valueFromTextFunction=[](const juce::String& value){return (double)SamplePitch::parse(value);};cents.setRange(-100,100,.1);cents.setTextValueSuffix(" cents");cents.setTextBoxStyle(juce::Slider::TextBoxRight,false,90,26);root.onValueChange=cents.onValueChange=[this]{if(binding||active<0||active>=(int)rows.size())return;rows[active].note=(int)root.getValue();rows[active].cents=cents.getValue();rows[active].status="Manual";rows[active].confidence=1;list.repaint();};
  sampleButton.setBounds(12,358,188,29);pianoButton.setBounds(208,358,230,29);detect.setBounds(446,358,252,29);retuneSelected.setBounds(12,394,224,30);retuneAll.setBounds(244,394,224,30);restore.setBounds(476,394,222,30);move.setBounds(12,431,224,29);status.setBounds(244,430,454,60);status.setFont(juce::FontOptions(11));status.setJustificationType(juce::Justification::centredLeft);
  root.setTooltip("Pitch of the active row. Drag or type a note such as C3. Correct it by ear before retuning.");retuneAll.setTooltip("Overwrite these files with pitch-shifted audio; retain duration, names, tags and favourites. Originals are backed up.");
  sampleButton.onClick=[this]{if(active<0||active>=(int)rows.size())return;auto file=rows[active].file;auto safe=juce::Component::SafePointer<OneShotPreparationPanel>(this);OneShotPreparation::jobs.addJob([safe,file]{auto data=OneShotPreparation::decode(file);juce::MessageManager::callAsync([safe,data]{if(safe&&data&&safe->audition)safe->audition(data);});});};pianoButton.onClick=[this]{if(active>=0&&active<(int)rows.size()&&rows[active].note>=0&&piano)piano(rows[active].note+rows[active].cents/100);};detect.onClick=[this]{analyse(true);};retuneSelected.onClick=[this]{retune(false);};retuneAll.onClick=[this]{retune(true);};move.onClick=[this]{if(moveFiles)moveFiles(selection(false));if(auto* box=findParentComponentOfClass<juce::CallOutBox>())box->dismiss();};restore.onClick=[this]{restoreLast();};startTimer(150);analyse(false);
 }
 ~OneShotPreparationPanel()override{if(stop)stop();}
private:
 int getNumRows()override{return (int)rows.size();}
 void paintListBoxItem(int index,juce::Graphics& g,int width,int height,bool selected)override{if(!juce::isPositiveAndBelow(index,(int)rows.size()))return;if(selected)g.fillAll(juce::Colour(0xff654442));g.setColour(juce::Colours::white);auto& item=rows[index];g.setFont(juce::FontOptions(12));g.drawFittedText(item.file.getFileName(),6,0,width-310,height,juce::Justification::centredLeft,1);g.setColour(item.note>=0?juce::Colours::lightgreen:juce::Colours::orange);g.drawText(item.note>=0?SamplePitch::name(item.note)+"  "+juce::String(item.cents,1)+"c":"Unknown",width-300,0,140,height,juce::Justification::centredLeft);g.setColour(juce::Colours::lightgrey);g.drawText(item.status,width-155,0,150,height,juce::Justification::centredLeft);}
 void selectedRowsChanged(int last)override{if(!juce::isPositiveAndBelow(last,(int)rows.size()))return;active=last;juce::ScopedValueSetter<bool> guard(binding,true);root.setValue(rows[last].note,juce::dontSendNotification);cents.setValue(rows[last].cents,juce::dontSendNotification);}
 juce::Array<juce::File> selection(bool all)const{juce::Array<juce::File> files;auto selected=list.getSelectedRows();for(int i=0;i<(int)rows.size();++i)if(all||selected.contains(i))files.add(rows[i].file);return files;}
 void timerCallback()override{bool can=!loading&&!OneShotPreparation::busy;root.setEnabled(can&&active>=0);cents.setEnabled(can&&active>=0);detect.setEnabled(can);retuneSelected.setEnabled(can&&list.getNumSelectedRows()>0);retuneAll.setEnabled(can&&!rows.empty());move.setEnabled(can&&list.getNumSelectedRows()>0);restore.setEnabled(can&&OneShotPreparation::latest().existsAsFile());status.setText(OneShotPreparation::busy?"Processing files in background...":loading?"Detecting pitches...":resultText.isNotEmpty()?resultText:"Overwrite preserves duration and filenames.\nWAV / AIFF / FLAC, up to 30 seconds. Originals backed up.",juce::dontSendNotification);}
 void analyse(bool force){if(loading||OneShotPreparation::busy)return;loading=true;auto files=selection(true);auto safe=juce::Component::SafePointer<OneShotPreparationPanel>(this);OneShotPreparation::jobs.addJob([safe,files,force]{std::vector<OneShotPreparation::Item> inspected;for(auto file:files){auto item=OneShotPreparation::inspect(file,force);item.audio.reset();inspected.push_back(std::move(item));}juce::MessageManager::callAsync([safe,inspected=std::move(inspected)]()mutable{if(!safe)return;safe->rows=std::move(inspected);safe->loading=false;safe->list.updateContent();if(!safe->rows.empty()){safe->list.selectRow(juce::jlimit(0,(int)safe->rows.size()-1,safe->active));safe->selectedRowsChanged(safe->list.getLastRowSelected());}safe->list.repaint();});});}
 void retune(bool all){if(loading||OneShotPreparation::busy.exchange(true))return;auto targets=selection(all);std::vector<OneShotPreparation::Item> chosen;for(auto& item:rows)if(targets.contains(item.file))chosen.push_back(item);if(chosen.empty()){OneShotPreparation::busy=false;return;}if(stop)stop();auto safe=juce::Component::SafePointer<OneShotPreparationPanel>(this);auto done=changed;OneShotPreparation::jobs.addJob([safe,chosen,targets,done]{auto result=OneShotPreparation::run(chosen);OneShotPreparation::busy=false;juce::MessageManager::callAsync([safe,result,targets,done]{if(done)done(targets);if(safe){safe->resultText=result;safe->analyse(false);}});});}
 void restoreLast(){if(loading||OneShotPreparation::busy.exchange(true))return;if(stop)stop();auto targets=selection(true);auto safe=juce::Component::SafePointer<OneShotPreparationPanel>(this);auto done=changed;OneShotPreparation::jobs.addJob([safe,targets,done]{auto result=OneShotPreparation::restore();OneShotPreparation::busy=false;juce::MessageManager::callAsync([safe,result,targets,done]{if(done)done(targets);if(safe){safe->resultText=result;safe->analyse(false);}});});}
};
